// #NOGTODO is the hashtag
PIXI={
	autoDetectRenderer:function(){
		this.plugins={interaction:{cursorStyles:{}}};
		this.resize=function(){};
		this.render=function(){};
	},
	RenderTexture:{
		create:function(){},
	},
	Container:function(){
		this.destroy=function(){};
		this.addChild=function(){};
		this.removeChild=function(){};
		this.removeChildren=function(){};
		this.on=function(){return this;};
		this.group={enableSort:true};
		this.x=0;
		this.y=0;
		this.children=[];
		this.visible=true;
		this.width=26;
		this.height=35;
		this.anchor={
			x:1,
			y:1,
			set:function(){},
		};
		this.position={
			set:function(x,y){ this.x=x; this.y=y; }
		}
	},
	Texture:function(){
	},
	Rectangle:function(){
	},
	Point:function(){
	},
	extras:{
	},
	filters:{
		OutlineFilter:function(){},
	},
	display:{
	},
	SCALE_MODES:{},
	RENDERER_TYPE:{},
	utils:{BaseTextureCache:{}},
	loader:{
		on:function(){},
		add:function(){},
		load:function(f){this.load_function=f;},
		load_function:function(){}
	},
	Graphics:function(){
		PIXI.Container.call(this);
		if(!PIXI._no_graphics_warning_shown){
			PIXI._no_graphics_warning_shown=true;
			if(typeof console!="undefined" && console.warn) console.warn("PIXI.Graphics was requested in No Graphics mode; drawing was skipped.");
		}
		var noop=function(){return this;};
		this.clear=noop;
		this.beginFill=noop;
		this.endFill=noop;
		this.lineStyle=noop;
		this.moveTo=noop;
		this.lineTo=noop;
		this.drawCircle=noop;
		this.drawRect=noop;
		this.drawRoundedRect=noop;
		this.drawPolygon=noop;
	}
}
Howl=function(){

}
PIXI.CanvasRenderer=PIXI.autoDetectRenderer;
PIXI.WebGLRenderer=PIXI.autoDetectRenderer;
PIXI.Sprite=PIXI.Container;
PIXI.Text=PIXI.Container;
PIXI.display.Stage=PIXI.Container;
PIXI.display.Layer=PIXI.Container;
PIXI.display.Group=PIXI.Container;
PIXI.extras.TilingSprite=PIXI.Container;
